    public virtual void handleTrades(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         data: {
        //             E: '1754601477746429',
        //             T: '1754601477744000',
        //             a: '5121860761',
        //             b: '5121861755',
        //             e: 'trade',
        //             m: false,
        //             p: '3870.25',
        //             q: '0.0008',
        //             s: 'ETH_USDC_PERP',
        //             t: 10782547
        //         },
        //         stream: 'trade.ETH_USDC_PERP'
        //     }
        //
        IDictionary<string, object> data = this.safeDict(message, "data", new Dictionary<string, object>() {});
        string? marketId = this.safeString(data, "s");
        Dictionary<string, object> market = this.market(marketId);
        string? symbol = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
        if (!((this.trades != null && symbol != null && this.trades.ContainsKey(symbol))))
        {
            Int64? limit = this.safeInteger(this.options, "tradesLimit", 1000);
            var stored = new ArrayCache(limit);
            this.trades[(string)symbol] = stored;
        }
        ccxt.pro.ArrayCache cache = ((ccxt.pro.ArrayCache)(this.trades != null && symbol != null && this.trades.ContainsKey(symbol) ? this.trades[symbol] : null));
        Dictionary<string, object> trade = this.parseWsTrade(data, market);
        cache.append(trade);
        string messageHash = ("trades:" + symbol);
        client.resolve(cache, messageHash);
        client.resolve(cache, "trades");
    }

    public override Dictionary<string, object> parseWsTrade(object trade, object market = null)
    {
        //
        //     {
        //         E: '1754601477746429',
        //         T: '1754601477744000',
        //         a: '5121860761',
        //         b: '5121861755',
        //         e: 'trade',
        //         m: false,
        //         p: '3870.25',
        //         q: '0.0008',
        //         s: 'ETH_USDC_PERP',
        //         t: 10782547
        //     }
        //
        Int64? microseconds = this.safeInteger(trade, "E", 0);
        Int64? timestamp = this.parseToInt(((double?)microseconds / 1000));
        string? id = this.safeString(trade, "t");
        string? marketId = this.safeString(trade, "s");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        bool? isBuyerMaker = this.safeBool(trade, "m");
        string? side = null;
        string? takerOrMaker = null;
        if ((isBuyerMaker != null))
        {
            takerOrMaker = "taker";
            if ((isBuyerMaker == true))
            {
                side = "sell";
            } else
            {
                side = "buy";
            }
        }
        string? price = this.safeString(trade, "p");
        string? amount = this.safeString(trade, "q");
        string? orderId = null;
        if (side == "buy")
        {
            orderId = this.safeString(trade, "b");
        } else
        {
            orderId = this.safeString(trade, "a");
        }
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "id", id },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", (marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("symbol") ? ((IDictionary<string, object>)marketResolved)["symbol"] : null) },
            { "order", orderId },
            { "type", null },
            { "side", side },
            { "takerOrMaker", takerOrMaker },
            { "price", price },
            { "amount", amount },
            { "cost", null },
            { "fee", new Dictionary<string, object>() {
                { "currency", null },
                { "cost", null },
            } },
        }, marketResolved);
    }

